package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.math.BigDecimal;
import java.net.InetSocketAddress;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

/**
 * Exercises {@link HttpPaymentGateway} against a real embedded HTTP server standing in for the
 * payment provider, so both what we send over the wire and how we interpret the provider's
 * answer are verified end to end.
 */
class HttpPaymentGatewayTest {

    private static final ObjectMapper JSON = new ObjectMapper();
    private static final Money AMOUNT = new Money(new BigDecimal("12.50"), "eur");

    private HttpServer server;
    private HttpPaymentGateway gateway;
    private final AtomicReference<String> lastRequestBody = new AtomicReference<>();
    private final AtomicReference<String> lastRequestPath = new AtomicReference<>();
    private final AtomicReference<String> lastContentType = new AtomicReference<>();

    @BeforeEach
    void startServer() throws IOException {
        server = HttpServer.create(new InetSocketAddress("localhost", 0), 0);
        server.start();
        var client = RestClient.builder().baseUrl("http://localhost:" + server.getAddress().getPort()).build();
        gateway = new HttpPaymentGateway(client);
    }

    @AfterEach
    void stopServer() {
        server.stop(0);
    }

    @Test
    void sends_the_reference_amount_and_currency_as_json_to_the_authorizations_endpoint() throws Exception {
        respondWith(200, "{\"status\":\"approved\"}");

        gateway.authorize("ORD-1", AMOUNT);

        assertThat(lastRequestPath.get()).isEqualTo("/v1/authorizations");
        assertThat(lastContentType.get()).contains("application/json");
        Map<?, ?> sent = JSON.readValue(lastRequestBody.get(), Map.class);
        assertThat(sent)
                .containsEntry("reference", "ORD-1")
                .containsEntry("amount", 12.50)
                .containsEntry("currency", "EUR");
    }

    @Test
    void an_approved_response_is_read_back_as_approved() throws Exception {
        respondWith(200, "{\"status\":\"approved\"}");

        var outcome = gateway.authorize("ORD-2", AMOUNT);

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_response_is_read_back_as_declined() throws Exception {
        respondWith(200, "{\"status\":\"declined\"}");

        var outcome = gateway.authorize("ORD-3", AMOUNT);

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void the_provider_refusing_the_payment_outright_with_402_is_read_back_as_declined() throws Exception {
        respondWith(402, "{\"error\":\"insufficient_funds\"}");

        var outcome = gateway.authorize("ORD-4", AMOUNT);

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_status_body_is_treated_as_declined_rather_than_approved() throws Exception {
        respondWith(200, "{\"status\":\"pending\"}");

        var outcome = gateway.authorize("ORD-5", AMOUNT);

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_provider_error_surfaces_as_a_failure_rather_than_being_swallowed() throws Exception {
        respondWith(500, "{\"error\":\"internal\"}");

        assertThatThrownBy(() -> gateway.authorize("ORD-6", AMOUNT))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }

    private void respondWith(int status, String body) throws IOException {
        server.createContext("/v1/authorizations", exchange -> {
            lastRequestPath.set(exchange.getRequestURI().getPath());
            lastContentType.set(exchange.getRequestHeaders().getFirst("Content-Type"));
            lastRequestBody.set(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));

            var bytes = body.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(status, bytes.length);
            try (var os = exchange.getResponseBody()) {
                os.write(bytes);
            }
        });
    }
}

